import corpusJson from "@/data/rag/psi-combustion-corpus.json";

/**
 * NASA PSI combustion-science corpus, generated by
 * `python scripts/NASAflamesRAG.py build` from the public PSI repository API.
 * Text is quoted from the investigation records; nothing here is written by IGNIS.
 */

export type PsiChunkField = "overview" | "objective" | "hypothesis" | "approach" | "researchImpacts" | "publications";

export interface PsiChunk {
  /** "<accession>#<field>-<n>", e.g. "PSI-25#objective-0". */
  id: string;
  field: PsiChunkField;
  text: string;
}

export interface PsiPublication {
  title: string;
  authors: string;
  doi: string;
}

export interface PsiInvestigation {
  accession: string;
  title: string;
  acronym: string;
  /** Public PSI record page. */
  url: string;
  doi: string;
  startDate: string;
  endDate: string;
  releaseDate: string;
  researchArea: string;
  subResearchArea: string;
  projectType: string;
  flightProgram: string;
  experimentHardware: string;
  managingCenter: string;
  license: string;
  principalInvestigators: string[];
  keywords: string[];
  relatedInvestigations: string[];
  objective: string;
  hypothesis: string;
  approach: string;
  researchImpacts: string;
  publications: PsiPublication[];
  files: { total: number; csv: number; pdf: number; spreadsheet: number; video: number; archive: number; experimentalTables: number };
  detailRetrieved: boolean;
  chunks: PsiChunk[];
}

export interface PsiCorpus {
  schemaVersion: number;
  retrievedAt: string;
  source: { name: string; search: string; searchFilter: string; detail: string; publicPage: string };
  chunking: { minWords: number; maxWords: number; fields: PsiChunkField[] };
  investigations: PsiInvestigation[];
}

export const PSI_CORPUS = corpusJson as PsiCorpus;

export const FIELD_LABEL: Record<PsiChunkField, string> = {
  overview: "Record overview",
  objective: "Objective",
  hypothesis: "Hypothesis",
  approach: "Approach",
  researchImpacts: "Research impacts",
  publications: "Publications",
};

export function psiInvestigation(accession: string): PsiInvestigation | null {
  return PSI_CORPUS.investigations.find((item) => item.accession === accession) ?? null;
}

/** "PSI-101 SAME-R", or the accession alone when the record has no acronym. */
export function psiLabel(investigation: Pick<PsiInvestigation, "accession" | "acronym">): string {
  return investigation.acronym ? `${investigation.accession} ${investigation.acronym}` : investigation.accession;
}
